/**
 * The client-side result of a right click on an entity, as vanilla predicts it: Entity.interactAt (before 26.1, only
 * the armor stand uses it), then Player.interactOn (Entity.interact / Mob.mobInteract, then the item's
 * interactLivingEntity). entityInteractData.json is generated by scripts/entities from the decompiled clients.
 */
import { Entity } from 'prismarine-entity'
import type { HandContext, InteractionResult } from './interactionRules'
import { getLatestEntityName } from './attackableEntity'
import data from './entityInteractData.json'
import { versionToNumber } from './utils'

interface Rule {
  entities: string[]
  item: string | string[]
  when?: string[]
  versions?: string
  result: string | Record<string, string>
}
interface ItemGroup {
  items?: Array<string | { name: string, versions?: string }>
  suffix?: string
  exclude?: string[]
  alias?: string
}

const table = data as unknown as {
  entityGroups: Record<string, { members: string[] }>
  itemGroups: Record<string, ItemGroup>
  conditions: Record<string, boolean>
  phases: { entity: Rule[], item: Rule[] }
}

interface Ctx {
  version: number
  entity: string
  item: string | null
  mainHand: boolean
  gameMode: string
  sneaking: boolean
  living: boolean
  meta: Record<string, boolean>
}

function inRange(version: number, range?: string) {
  if (!range) return true
  return range.trim().split(/\s+/).every(c => {
    const m = /^(>=|<=|>|<|=)?(.+)$/.exec(c)!
    const op = m[1] || '='
    const d = Math.sign(version - versionToNumber(m[2]!))
    return op === '>=' ? d >= 0 : op === '<=' ? d <= 0 : op === '>' ? d > 0 : op === '<' ? d < 0 : d === 0
  })
}

function groupHas(group: string, ctx: Ctx) {
  if (group === 'living') return ctx.living
  if (group === 'mob') return ctx.living && !table.entityGroups.livingNonMob!.members.includes(ctx.entity)
  return table.entityGroups[group]?.members.includes(ctx.entity) ?? false
}

function itemInGroup(groupName: string, item: string, version: number): boolean {
  let group = table.itemGroups[groupName]
  if (!group) return false
  if (group.alias) group = table.itemGroups[group.alias]!
  if (group.exclude?.includes(item)) return false
  if (group.suffix && item.endsWith(group.suffix)) return true
  return (group.items ?? []).some(e => (typeof e === 'string' ? e === item : e.name === item && inRange(version, e.versions)))
}

function itemMatches(matcher: string | string[], ctx: Ctx): boolean {
  if (Array.isArray(matcher)) return matcher.some(m => itemMatches(m, ctx))
  const { item } = ctx
  if (matcher === 'any') return true
  if (matcher === 'empty') return !item
  if (matcher === 'nonEmpty') return !!item
  if (!item) return false
  if (matcher === '#food:self') return itemInGroup(`food:${ctx.entity}`, item, ctx.version)
  if (matcher.startsWith('#')) return itemInGroup(matcher.slice(1), item, ctx.version)
  return matcher === item
}

function evalCond(expr: string, ctx: Ctx): boolean {
  let i = 0
  const s = expr.replace(/\s+/g, '')
  const ident = (id: string): boolean => {
    if (id.startsWith('entity=')) return ctx.entity === id.slice(7)
    if (id === 'sneaking') return ctx.sneaking
    if (id === 'mainHand') return ctx.mainHand
    if (id === 'creative') return ctx.gameMode === 'creative'
    if (id in ctx.meta) return ctx.meta[id]!
    if (id === 'hasShearableEquipment') return !!(ctx.meta.saddled || ctx.meta.wearingBodyArmor)
    if (id === 'leashableNow') return groupHas('leashable', ctx) && !ctx.meta.leashed && !(ctx.entity === 'wolf' && ctx.meta.angry)
    if (id === 'spawnEggMatchesEntity') return ctx.item === `${ctx.entity}_spawn_egg`
    if (id === 'leashedToAnyPlayer') return !!ctx.meta.leashedToPlayer
    return table.conditions[id] ?? false
  }
  const atom = (): boolean => {
    if (s[i] === '!') {
      i++
      return !atom()
    }
    if (s[i] === '(') {
      i++
      const v = or()
      i++
      return v
    }
    const m = /^[A-Za-z0-9_=:]+/.exec(s.slice(i))!
    i += m[0].length
    return ident(m[0])
  }
  const and = (): boolean => {
    let v = atom()
    while (s[i] === '&') {
      i++
      const r = atom()
      v = v && r
    }
    return v
  }
  const or = (): boolean => {
    let v = and()
    while (s[i] === '|') {
      i++
      const r = and()
      v = v || r
    }
    return v
  }
  return or()
}

function runPhase(rules: Rule[], ctx: Ctx): string {
  for (const r of rules) {
    if (!inRange(ctx.version, r.versions)) continue
    if (!r.entities.some(e => e === '*' || e === ctx.entity || (e.startsWith('@') && groupHas(e.slice(1), ctx)))) continue
    if (!itemMatches(r.item, ctx)) continue
    if (r.when && !r.when.every(w => evalCond(w, ctx))) continue
    const result = typeof r.result === 'string' ? r.result : Object.entries(r.result).find(([range]) => inRange(ctx.version, range))?.[1]
    if (result == null) continue
    return result
  }
  return 'pass'
}

const LIVING_TYPES = new Set(['mob', 'animal', 'living', 'ambient', 'hostile', 'water_creature', 'passive', 'player'])

/** what the client knows of the entity from its metadata */
function entityMeta(ctx: HandContext, entity: Entity, name: string): Record<string, boolean> {
  const keys = ctx.data.entitiesByName[entity.name ?? '']?.metadataKeys
  const meta: Record<string, boolean> = {}
  if (Array.isArray((entity as any).passengers)) meta.vehicle = (entity as any).passengers.length > 0
  // mineflayer keeps the leash holder (attach_entity, the leash packet from 1.9) as the entity's vehicle
  const holder = (entity as any).vehicle
  if (holder) {
    meta.leashed = true
    meta.leashedToPlayer = !!ctx.bot.entity && holder.id === ctx.bot.entity.id
  }
  if (!keys) return meta
  const value = (key: string) => {
    const index = keys.indexOf(key)
    return index >= 0 ? (entity.metadata as any)?.[index] : undefined
  }
  const baby = value('baby') ?? value('is_baby')
  if (baby !== undefined) meta.baby = !!baby
  const saddle = value('saddle')
  if (saddle !== undefined) meta.saddled = !!saddle
  const flags = value('flags')
  if (flags !== undefined) {
    if (/horse|donkey|mule|llama|camel/.test(name)) {
      meta.tamed = (Number(flags) & 0x02) !== 0
      if ((Number(flags) & 0x04) !== 0) meta.saddled = true
    } else {
      meta.tamed = (Number(flags) & 0x04) !== 0
    }
  }
  const wool = value('wool')
  if (wool !== undefined) meta.sheared = (Number(wool) & 0x10) !== 0
  if (/item_frame/.test(name)) {
    const item = value('item')
    meta.frameHasItem = !!item && item.present !== false && (item.itemCount ?? 1) > 0
  }
  const response = value('response')
  if (response !== undefined) meta.interactionResponse = !!response
  const clientFlags = value('client_flags')
  if (name === 'armor_stand' && clientFlags !== undefined) meta.armorStandMarker = (Number(clientFlags) & 16) !== 0
  return meta
}

/** interactAt (the armor stand, before 26.1) and interact, as the client predicts them */
export function entityInteractResult(ctx: HandContext, entity: Entity): { interactAt: InteractionResult, interact: InteractionResult } {
  const name = getLatestEntityName(entity.name ?? '') ?? entity.name ?? ''
  const type = ctx.data.entitiesByName[entity.name ?? '']?.type
  const c: Ctx = {
    version: versionToNumber(ctx.data.version.minecraftVersion!),
    entity: name,
    item: ctx.item?.name ?? null,
    mainHand: ctx.hand === 0,
    gameMode: ctx.gameMode,
    sneaking: ctx.sneaking,
    living: type ? LIVING_TYPES.has(type) || name === 'armor_stand' : !/boat|raft|minecart|frame|knot|interaction|crystal|painting/.test(name),
    meta: entityMeta(ctx, entity, name)
  }
  let result = runPhase(table.phases.entity, c)
  if ((result === 'pass' || result === 'fail') && c.item && c.living) {
    const itemResult = runPhase(table.phases.item, c)
    if (itemResult !== 'pass' && itemResult !== 'fail') result = itemResult
  }
  // fail behaves as pass for an entity: the hand loop only stops on a success
  const r: InteractionResult = result === 'success' || result === 'consume' ? result : 'pass'
  // before 26.1 the armor stand's use is its interactAt
  if (name === 'armor_stand' && ctx.version['<']('26.1')) return { interactAt: r, interact: 'pass' }
  return { interactAt: 'pass', interact: r }
}
